//! Places and releases indefinite receipt and order holds atomically with audit evidence.
use crate::{Audit, Error, Store, key};
use analyte_model::{Identifier, ReceiptId};
use rusqlite::params;
use serde::{Deserialize, Serialize};

/// Explicit hold scope; an order hold covers all receipts linked to that order.
#[derive(Clone, Serialize, Deserialize)]
pub enum HoldTarget {
    /// One receipt generated by Analyte.
    Receipt(ReceiptId),
    /// One lab app order in its destination namespace.
    Order {
        /// Lab app destination.
        destination: Identifier,
        /// App order identity.
        order: Identifier,
    },
}
impl HoldTarget {
    fn columns(&self) -> Result<(&'static str, String), Error> {
        match self {
            Self::Receipt(receipt) => Ok(("receipt", key(receipt)?)),
            Self::Order { destination, order } => Ok(("order", key(&(destination, order))?)),
        }
    }
}
impl Store {
    /// Changes a hold with no expiry and writes actor, reason, target and time atomically.
    /// # Errors
    /// Refuses unknown/purged targets, repeated transitions, bounds and storage failures.
    pub fn set_retention_hold(
        &mut self,
        target: &HoldTarget,
        active: bool,
        audit: &Audit,
    ) -> Result<(), Error> {
        let (kind, target_key) = target.columns()?;
        match target {
            HoldTarget::Receipt(id) => {
                if self.receipt_metadata(*id)?.is_none() {
                    return Err(Error::UnknownReceipt);
                }
            }
            HoldTarget::Order { destination, order } => {
                if self.cached_order(destination, order)?.is_none() {
                    return Err(Error::InvalidInput);
                }
            }
        }
        let action = if active {
            "retention-hold-place"
        } else {
            "retention-hold-release"
        };
        let encoded = self.encode(&(action, target, audit))?;
        self.capacity(encoded.len())?;
        let tx = self.db.transaction()?;
        let changed = if active {
            tx.execute("INSERT INTO retention_holds(kind,target,active) VALUES (?1,?2,1) ON CONFLICT(kind,target) DO UPDATE SET active=1 WHERE active=0", params![kind,target_key])?
        } else {
            tx.execute(
                "UPDATE retention_holds SET active=0 WHERE kind=?1 AND target=?2 AND active=1",
                params![kind, target_key],
            )?
        };
        if changed != 1 {
            return Err(Error::Conflict);
        }
        tx.execute("INSERT INTO audit(evidence) VALUES (?1)", [encoded])?;
        tx.commit()?;
        Ok(())
    }
    /// Reports an explicit hold; order coverage is additionally checked during eligibility.
    /// # Errors
    /// Reports encoding and storage failures.
    pub fn retention_hold(&self, target: &HoldTarget) -> Result<bool, Error> {
        let (kind, target) = target.columns()?;
        Ok(self.db.query_row(
            "SELECT EXISTS(SELECT 1 FROM retention_holds WHERE kind=?1 AND target=?2 AND active=1)",
            params![kind, target],
            |r| r.get(0),
        )?)
    }
}
